    @classmethod
    def Wave(cls, vector: Vector=None, scale: Float=None, distortion: Float=None, detail: Float=None, detail_scale: Float=None, detail_roughness: Float=None, phase_offset: Float=None, wave_type: Literal['BANDS', 'RINGS']='BANDS', bands_direction: Literal['X', 'Y', 'Z', 'DIAGONAL']='X', rings_direction: Literal['X', 'Y', 'Z', 'SPHERICAL']='X', wave_profile: Literal['SIN', 'SAW', 'TRI']='SIN'):
        """ > Node <&ShaderNode Wave Texture>
        
        Parameters
        ----------
        vector : Vector, optional
            socket 'Vector'
        
        scale : Float, optional
            socket 'Scale'
        
        distortion : Float, optional
            socket 'Distortion'
        
        detail : Float, optional
            socket 'Detail'
        
        detail_scale : Float, optional
            socket 'Detail Scale'
        
        detail_roughness : Float, optional
            socket 'Detail Roughness'
        
        phase_offset : Float, optional
            socket 'Phase Offset'
        
        wave_type : Literal['Bands', 'Rings']
            parameter `wave_type`
        
        bands_direction : Literal['X', 'Y', 'Z', 'Diagonal']
            parameter `bands_direction`
        
        rings_direction : Literal['X', 'Y', 'Z', 'Spherical']
            parameter `rings_direction`
        
        wave_profile : Literal['Sine', 'Saw', 'Triangle']
            parameter `wave_profile`
        
        Returns
        -------
        Socket
            socket 'OUT'
        """
        node = Node('Wave Texture', named_sockets={'Vector': vector, 'Scale': scale, 'Distortion': distortion, 'Detail': detail, 'Detail Scale': detail_scale, 'Detail Roughness': detail_roughness, 'Phase Offset': phase_offset}, wave_type=wave_type, bands_direction=bands_direction, rings_direction=rings_direction, wave_profile=wave_profile)
        return node._out

    @classmethod
    def WhiteNoise(cls, vector: Vector=None, w: Float=None, noise_dimensions: Literal['1D', '2D', '3D', '4D']='3D'):
        """ > Node <&ShaderNode White Noise Texture>
        
        Parameters
        ----------
        vector : Vector, optional
            socket 'Vector'
        
        w : Float, optional
            socket 'W'
        
        noise_dimensions : Literal['1D', '2D', '3D', '4D']
            parameter `noise_dimensions`
        
        Returns
        -------
        Socket
            socket 'OUT'
        """
        _configuration = ({'1d': '1D', '2d': '2D', '3d': '3D', '4d': '4D'}.get(noise_dimensions.lower(), noise_dimensions),)
        _node_sockets = {('1D',): {'W': w}, ('2D',): {'Vector': vector}, ('3D',): {'Vector': vector}, ('4D',): {'Vector': vector, 'W': w}}[_configuration]
        _node_args = {('1D',): [], ('2D',): [], ('3D',): [], ('4D',): []}[_configuration]
        node = Node('White Noise Texture', *_node_args, named_sockets=_node_sockets, noise_dimensions=noise_dimensions)
        return node._out
